#include <stdio.h>
#include <stdlib.h>

#define MAXV 8

int main(int argc, char *argv[]) {
    // The original expects an even argc (program name + odd number of parameters)
    if ((argc & 1) != 0) {
        puts("INVALID_INPUT");
        return 1;
    }

    int adj[MAXV][MAXV] = {{0}};
    int indeg[MAXV] = {0};
    int done[MAXV] = {0};

    for (int i = 1; i + 1 < argc; i += 2) {
        long src = strtol(argv[i], NULL, 10);
        long dst = strtol(argv[i + 1], NULL, 10);
        if (src < 0 || src >= MAXV || dst < 0 || dst >= MAXV) {
            puts("INVALID_INPUT");
            return 1;
        }
        if (!adj[src][dst]) {
            adj[src][dst] = 1;
            indeg[dst]++;
        }
    }

    int stack[MAXV];
    int top = 0;
    int processed = 0;
    for (int v = 0; v < MAXV; ++v) {
        if (indeg[v] == 0) {
            stack[top++] = v;
            done[v] = 1;
        }
    }

    while (top > 0) {
        int u = stack[--top];
        printf("%d", u);
        ++processed;
        for (int v = 0; v < MAXV; ++v) {
            if (adj[u][v]) {
                indeg[v]--;
                if (indeg[v] == 0 && !done[v]) {
                    stack[top++] = v;
                    done[v] = 1;
                }
            }
        }
    }

    if (processed < MAXV) {
        puts("CYCLE");
        return 1;
    }
    return 0;
}
